# Create the output by expanding each cell to 3x3
test_input = [[3], [3], [0], [3]]

output = []
for row in test_input:
    for _ in range(3):  # Expand height by 3
        for cell in row:
            output.extend([cell] * 3)  # Expand width by 3
    output = [[output[j] for j in range(len(output) // len(test_input[0]))] * (len(test_input[0]])][0]  # Rebuild rows properly

# Simpler approach:
output = []
for r, row in enumerate(test_input):
    expanded_row = []
    for c, cell in enumerate(row):
        for _ in range(3):
            expanded_row.append(cell)
    for _ in range(3):
        output.append(expanded_row)

print("Output grid:")
for row in output:
    print(row)

